	.size	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.4887, 15

	.type	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.4888,@object
	.section	.rodata..Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.4888,"a",@progbits
.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.4888:
	.ascii	"A SHACL 1.2 sh:reifierShape constraint judges the reifiers of each value's triple, which the projected value does not carry, so the constraint is dropped."
	.size	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.4888, 154

	.type	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.4889,@object
