	.size	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.4889, 22

	.type	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.4890,@object
	.section	.rodata..Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.4890,"a",@progbits
.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.4890:
