	.type	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.4894,@object
	.section	.rodata..Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.4894,"a",@progbits
.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.4894:
	.ascii	"A value-vocabulary class projected to an enum $def has no seeded named-individual members to enumerate; the $def is emitted with an empty enum and the omission is recorded."
	.size	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.4894, 172

