	.type	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.5995,@object
.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.5995:
	.asciz	"\026unsupported construct \300N -- not defined by the XSD/XPath regExp grammar (XML Schema Part 2 Appendix G)"
	.size	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.5995, 104

	.type	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.5996,@object
	.section	.rodata..Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.5996,"a",@progbits
.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.5996:
	.asciz	"\016backreference \300\200\356\000 is not supported -- this is a permanent limitation of this implementation, which translates patterns onto a DFA-based regex engine that cannot backtrack, and no rewriting of the source text can reach a capability the engine does not have"
	.size	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.5996, 258

	.type	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.5997,@object
	.section	.rodata.str1.1,"aMS",@progbits,1
.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.5997:
	.asciz	" unrecognized Unicode block name \300\" in a \\p{...}/\\P{...} block escape"
	.size	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.5997, 70

	.type	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.5998,@object
.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.5998:
	.asciz	"#unrecognized Unicode property name \300\200\024\002 in a \\p{...}/\\P{...} escape: XML Schema Part 2 Appendix G's charProp admits only one of its general-category names (L, Lu, Ll, Lt, Lm, Lo, M, Mn, Mc, Me, N, Nd, Nl, No, P, Pc, Pd, Ps, Pe, Pi, Pf, Po, Z, Zs, Zl, Zp, S, Sm, Sc, Sk, So, C, Cc, Cf, Co, Cn) or an 'Is'-prefixed Unicode block name; Unicode scripts such as \"Greek\", 'key=value'/'key:value' property keys, and regex-crate pseudo-properties are not part of the XSD/XPath dialect -- a script is a different set from a block, so for the Greek block write \\p{IsGreekandCoptic}"
	.size	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.5998, 573

	.type	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.5999,@object
	.section	.rodata..Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.5999,"a",@progbits
.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.5999:
	.ascii	"malformed pattern: pattern ends with a dangling backslash"
	.size	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.5999, 57

	.type	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6000,@object
	.section	.rodata..Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6000,"a",@progbits
.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6000:
	.ascii	"malformed pattern: unterminated character class (missing closing ']')"
	.size	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6000, 69

	.type	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6001,@object
	.section	.rodata..Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6001,"a",@progbits
.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6001:
	.ascii	"malformed pattern: unescaped '[' inside a character class -- XML Schema Part 2 Appendix G's charGroup defines no nested character class there, so regex-syntax's nested-class union is a different language; a literal '[' must be escaped as '\\['"
	.size	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6001, 242

	.type	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6002,@object
	.section	.rodata..Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6002,"a",@progbits
.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6002:
	.ascii	"malformed pattern: unescaped ']' outside a character class -- it only ever closes a character class in the XSD/XPath grammar, and a literal one must be escaped as '\\]'"
	.size	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6002, 167

	.type	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6003,@object
	.section	.rodata..Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6003,"a",@progbits
.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6003:
	.ascii	"malformed pattern: literal ']' at the head of a character class -- XSD's charGroup requires at least one member, and a literal ']' must be escaped as '\\]'"
	.size	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6003, 154

	.type	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6004,@object
	.section	.rodata.str1.1,"aMS",@progbits,1
.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6004:
	.asciz	"\023malformed pattern: \300\2002\001 follows a character-class subtraction operand -- XML Schema Part 2 Appendix G's charGroup ::= (posCharGroup | negCharGroup) ('-' charClassExpr)? makes the subtraction the LAST element of the group, so only the enclosing ']' may follow it; there is at most one subtraction per group and no trailing members"
	.size	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6004, 331

	.type	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6005,@object
	.section	.rodata..Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6005,"a",@progbits
.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6005:
	.asciz	"\023malformed pattern: \300\200\360\000 is not a construct of the XSD/XPath regular-expression grammar (XML Schema Part 2 Appendix G defines no inline-flag, lookaround, comment, or named-group syntax); the only `(?` group spelling the grammar has is the non-capturing group `(?:`"
	.size	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6005, 265

	.type	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6006,@object
	.section	.rodata..Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6006,"a",@progbits
.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6006:
	.ascii	"malformed pattern: \\0 is not a construct of the XSD/XPath regular-expression grammar (a back-reference starts at \\1, and \\0 is not a single-character escape)"
	.size	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6006, 157

	.type	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6007,@object
	.section	.rodata..Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6007,"a",@progbits
.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6007:
	.asciz	"\024malformed pattern: \\\300\200\313\000 is not a construct of the XSD/XPath regular-expression grammar -- XML Schema Part 2 Appendix G enumerates its single-character escapes exactly (\\n \\r \\t \\\\ \\| \\. \\? \\* \\+ \\( \\) \\{ \\} \\- \\[ \\] \\^), and \\\310\000\000\022 is not among them"
	.size	.Lanon.613f6dc44e7c5dae8ce40a9bc4110ef5.6007, 251

